# -*- coding: utf-8 -*-
"""Stage 3 merge for report 62 (Streaks – Daily Habit Tracker, yusuf kildan)."""
import json
C = {x["id"]: x for x in json.load(open("Tools/prd_ledger/canonical.json"))}
def ext(cid, text):
    if text not in C[cid]["statement"]: C[cid]["statement"] += text
def add(cid, section, title, statement):
    if cid in C: return
    C[cid] = dict(id=cid, title=title, statement=statement, section=section, cards=[], reports=[], merged_from=[])

add("C278", "dont", "Do not name the app after an established competitor — a name collision makes the product 'the fake one' before it is tried, and the cost cannot be measured from reviews",
    "Report 62 (Streaks – Daily Habit Tracker by yusuf kildan, 45 reviews): 'If you are planning to get such app based on online review them do not download this app. This is fake and similar name app to the original one. The og has orange colour logo' (IN, 1★) — the collision is real and corroborated in this repository: folder 23 is Streaks by Crunchy Bagel Pty Ltd (app ID 963034692, 7,270 reviews vs this app's 45), so a user searching 'Streaks' meets both and the smaller app is 'losing on brand identity before the product is even tried'; the icon-colour claim could not be verified; how much the collision costs in installs is a research question the corpus cannot answer. Related: [[C184]] (a neutral name is already tested), [[C134]] (lead the listing with what users love), [[C114]] (ads must match the app).")

ext("C031", " Report 62 (Streaks, yusuf kildan): a 1–2 June 2026 build with broken hit-testing — taps did not register (six reviewers; one found that a swipe still worked) — produced 8 reviews in 39 hours across six storefronts (17.78% of the app's entire written history, 40% of all its 1★, −0.32 on the mean), caught a premium buyer and a $10 buyer one week after purchase, and blocked first-run habit creation ('I couldn't get past the start creating a habit step, the button won't press'); fixed within days (16 reviews from 3 Jun average 3.875, zero tap reports) but 'the regression is closed; the reviews it produced are not'.")
ext("C156", " Report 62 (Streaks, yusuf kildan): I3 — a regression gate on tap / hit-testing before release plus a fast rollback path; 'nothing in this corpus suggests a process change prevented the next one' and one bad build cost ~0.32 stars on the whole written history.")
ext("C175", " Report 62 (Streaks, yusuf kildan): 'Seems like each time when it updates the habits progress for the last week wipes. These happened two times already' (KZ, 2★, Aug 2026) and a total loss on launch ten months earlier — present before the June regression and still present after it was fixed; I4: treat habit history as migration-critical data with an integrity check on upgrade — 'in a streak product, destroyed history destroys the only thing the user has accumulated'.")
ext("C034", " Report 62 (Streaks, yusuf kildan): 'After several months of usage all my habits disappeared upon app launch' (UA, 1★); a repeating last-week wipe on update (KZ) — two reviews (4.44%) promoted under the severe-data-loss rule.")
ext("C139", " Report 62 (Streaks, yusuf kildan): the clearest case — 'If I don't have internet access the app asks me to go premium, when I already bought the app. This is a headache. Can you fix this critical error!' (EC, 5★ despite the bug): a receipt check that requires the network re-paywalls exactly the offline moments (commute, flight, poor signal) when a habit app is used; I1: cache the receipt / entitlement locally and never re-paywall a verified purchaser because the network is unavailable — 'the single highest-severity non-burst finding in this report'.")
ext("C033", " Report 62 (Streaks, yusuf kildan): 'I paid for subscription monthly but still not working. Is this scam?' (BR, 1★) — two of six self-identified payers had an entitlement failure, 'the worst ratio in this report'; I2: audit the purchase-unlock path end to end, including a charged subscription that still behaves as free.")
ext("C065", " Report 62 (Streaks, yusuf kildan): 5 of 6 self-identified payers report a defect or shortfall — two entitlement failures, two hit by the June build, one lifetime buyer disappointed by the widget; only one paid reviewer is unreservedly happy ('Worth every penny'); notably neither failed purchaser asked for a refund — both asked for a fix.")
ext("C007", " Report 62 (Streaks, yusuf kildan): a 3-habit free cap is the most-named boundary — 4 of 45 (8.89%) and all four say 3, rated 5★ / 3★ / 2★ / 1★ ('Just a small suggestion to add… at least one more free task as we already have 3 but having 4 as free will give edge to the app', 5★; 'the free version only allows tracking 3 habits… so I ended up uninstalling' after a paragraph of praise; 'Only 3?????? … this app is useless') — 'not a complaint from people who dislike the app; it is a wall that people walk into on their way out'; the use cases described (water and steps, walking, three concurrent religious practices) need 4–6 habits, so the cap bites before the product proves itself; steady across 17 months; M1: raise the allowance from 3 to 5, or make the 4th habit a time-limited trial rather than a wall.")
ext("C222", " Report 62 (Streaks, yusuf kildan): a fixed cap of 3, unchanged over 17 months, produces a steady trickle of cap reviews from otherwise satisfied users; the report's alternative to a raise is a time-limited 4th habit — a pressure valve rather than a moved wall.")
ext("C133", " Report 62 (Streaks, yusuf kildan): the price is not the problem (three unprompted 'the price is fair' against two one-line objections) — 'packaging (what the free tier contains) and delivery (whether the purchase works) are'; repackage, do not reprice.")
ext("C064", " Report 62 (Streaks, yusuf kildan): three reviewers volunteer that the price is good ('The price is also very affordable considering the features it offers'; 'the subscription prices are very good'; 'reasonably priced' — and still did not buy, over the sync gap) against two one-line objections ('It's paid'; 'Asked for a payment in simple app like this') — §8.5: do not raise prices and do not cut them.")
ext("C214", " Report 62 (Streaks, yusuf kildan): 'Asked for a payment in simple app like this' (MN, 1★) — an objection to paying for simplicity, the flip side of the app's own positioning; one of only two flat price objections in 45 reviews.")
ext("C177", " Report 62 (Streaks, yusuf kildan): 'What is the difference between the 34 and 59 paid subscription?' — a buyer had to publish a 5★ review to ask, because the paywall did not answer it; M2: differentiate the two tiers on the paywall itself.")
ext("C003", " Report 62 (Streaks, yusuf kildan): a one-time option was requested in Apr 2025 and a lifetime purchase reported in Jun 2026 — probably added in between; 'if it exists and is still being asked for, that is discoverability, not roadmap' (M4: surface the lifetime SKU more prominently).")
ext("C107", " Report 62 (Streaks, yusuf kildan): the large heat-map widget is the only named purchase trigger in the corpus ('I bought the paid version of the app (single month), because I wanted to use the larger widget showing the entire heat map and i absolutely love it') and the credited retention mechanism ('Without it I would underestimate the progress and tend to give up… I was able to successfully track and build new habits for the first time with this app'), while a lifetime buyer's only complaint is that it is too basic ('no dark themed widget? Widget so basic? Please step it up, I just paid for lifetime access') and another wants it to surface the next unfinished habit; M3: make the widget the explicit centre of the paid offer; P2: dark theme and a next-unfinished mode — 'highest leverage per unit of work'.")
ext("C023", " Report 62 (Streaks, yusuf kildan): a widget that shows the next unfinished habit is requested (UZ, 4★); widgets are credited with the strongest outcome statement in the corpus.")
ext("C040", " Report 62 (Streaks, yusuf kildan): the widget is the paid hook, so its gaps are voiced by the highest-LTV buyer — no dark theme, 'so basic' — from a lifetime purchaser.")
ext("C006", " Report 62 (Streaks, yusuf kildan): 11 of 45 (24.44%, mean 4.45) praise simplicity in six languages ('Sade ve kullanışlı'; 'Solo check y a seguir. Como debe ser'), including the user uninstalling over the cap ('Really clean, minimal UI… no-nonsense layout') — the moat is not in dispute even among 1★ reviewers; nothing asks for a busier main screen, the 4★ band asks for depth without complexity ('It's minimalistic I get it, but…'); design implication: every roadmap item additive-on-demand, not surfaced by default.")
ext("C264", " Report 62 (Streaks, yusuf kildan): 'just check and carry on. As it should be' — one-tap check-off is the praised loop; when the June build broke tapping, the app was unusable.")
ext("C143", " Report 62 (Streaks, yusuf kildan): within-day granularity is the largest coherent feature gap — 4 of 45 (8.89%) from four storefronts over eight months: count a habit N times a day and sum at day end, more than one reminder a day ('One reminder a day is not enough' for water and steps), a value per day ('walked 5k, then 7k'); two described use cases (water, steps) are currently unserviceable; P1 in the roadmap.")
ext("C014", " Report 62 (Streaks, yusuf kildan): one reminder per day only — 'Please make it possible to have reminders several times a day, so you can set a reminder to drink water or walk steps' (TJ, 3★).")
ext("C048", " Report 62 (Streaks, yusuf kildan): 'store a value or note per day (walked 5k, then 7k) and see it over time' (ZA, 4★) — the same data-model change as within-day counting (P5).")
ext("C172", " Report 62 (Streaks, yusuf kildan): a per-day value / note ('walked 5k, then 7k') requested by a 4★ reviewer.")
ext("C256", " Report 62 (Streaks, yusuf kildan): 'unlimited back-dating makes streaks less meaningful' — a fan asks to mark missed days explicitly (a cross / red mark) and to lock past days; P4: streak integrity as an option, because some users need back-fill, and §8.5: do not remove back-dating — make it lockable.")
ext("C010", " Report 62 (Streaks, yusuf kildan): any past day can be edited and a premium buyer was actively using the edit-previous-day buttons when the June build broke them; the counter-request is a lock, not removal.")
ext("C013", " Report 62 (Streaks, yusuf kildan): 'looked really promising and reasonably priced, but does not let you sync between your Phone and iPad' (US, 1★) — a willing buyer who did not buy solely for this; 'revenue-blocking, not cosmetic'.")
ext("C217", " Report 62 (Streaks, yusuf kildan): 'you see a sea of dots without being able to distinguish month, week and day' (IT, 1★) — the dot / heat-map grid others paid for carries no time axis, and a 4★ asks for the options to be explained: 'the UI is legible to people who already understand it'; P8: a visible month / week / day framing as a design test; P7: one-line hints on first use.")
ext("C075", " Report 62 (Streaks, yusuf kildan): 'Explain what the options actually do' (PY, 4★) — the cheapest item in the report.")
ext("C012", " Report 62 (Streaks, yusuf kildan): statistics are not on the main screen and have to be sought out — named as a reason a 4★ is 'consider[ing] other options'; P6: reachable from the main screen without adding clutter.")
ext("C021", " Report 62 (Streaks, yusuf kildan): 'It doesn't communicate with iPhone Health-fitness; it said it did' (TR, 2★) — if the listing promises it, an expectation mismatch, worse than an absent feature; I5: make the link work or remove the claim, the cheapest immediate fix.")
ext("C218", " Report 62 (Streaks, yusuf kildan): a Health integration a reviewer believed was advertised does not work — 'either make it work, or remove the claim'.")
ext("C022", " Report 62 (Streaks, yusuf kildan): an Apple Watch app requested once (UZ, 4★); treated as absent as of Jan 2026, lowest priority of the set.")
ext("C093", " Report 62 (Streaks, yusuf kildan): 'Get one star for annoying me with pop-ups' (PL, 1★) — one review, a full star, 'a setting, not a build'; M5: cut in-session upsell pop-ups or cap their frequency.")
ext("C042", " Report 62 (Streaks, yusuf kildan): an Arabic reviewer became consistent with morning adhkār, dhikr and daily Qur'an reading ('even if just a page') and advises others to include remembrance of God in their habit — a religious-practice use case the 'Atomic Goals & Accountability' positioning does not address, already running 3+ habits, i.e. over the free cap.")
ext("C140", " Report 62 (Streaks, yusuf kildan): use cases described — fitness / sport progress, hydration and step counts (unserved by a binary daily check), religious practice, daily task focus; no review describes breaking a bad habit despite the accountability subtitle.")
ext("C131", " Report 62 (Streaks, yusuf kildan): no review asks for sharing, friends, leaderboards or accountability partners — §8.5: do not chase the 'accountability' positioning with social features.")
ext("C246", " Report 62 (Streaks, yusuf kildan): zero ad complaints in 45 reviews; §8.5: do not build ads — 'a habit app whose appeal is calm minimalism has more to lose than to gain'.")
ext("C231", " Report 62 (Streaks, yusuf kildan): 45 written reviews vs 536 public ratings (8.40%), written mean 3.111 vs public 4.52 — 'the written corpus is a complaint channel, not a satisfaction measure'; per storefront the gap runs to −3.56 (UA: 39 ratings at 4.56 vs two 1★ reviews) and Ireland's one 1★ review is its entire public rating; Argentina is the one storefront where the June burst shows in the public number (3.82).")
ext("C062", " Report 62 (Streaks, yusuf kildan): on 11 high-spend reviews (3.455) vs 26 high-volume (2.846), high-spend reviewers ask for capability (sync, statistics, granularity, legibility) and none objects to the price, while high-volume and long-tail reviewers raise access (the cap, paying at all) — 'consistent with the corpus but not established by it'; India is the most product-engaged storefront (both widget-outcome reviews, the streak-integrity request, the purchase trigger and the brand risk) and the one the report says to research.")
ext("C094", " Report 62 (Streaks, yusuf kildan): three of 17 five-star reviews (17.6% of the band) do not endorse the product — 'App doesn't work', a pricing question, a critical entitlement bug — so the public 5★ count overstates satisfaction by roughly that much; seven low-information 5★ ('Good', '👍🏻', 'Excelente') are evenly spread.")
ext("C059", " Report 62 (Streaks, yusuf kildan): zero customer-support mentions in 45 reviews — nobody reports contacting the developer, including the three whose app broke after paying; failed purchasers asked for a fix, not a refund.")
ext("C036", " Report 62 (Streaks, yusuf kildan): no reviewer — including three paying customers with a broken app — reports contacting the developer; the reviews are the support channel by default.")
ext("C005", " Report 62 (Streaks, yusuf kildan): 'From what i have tested this one is the one i liked the most' (won a comparison shop); a 4★ considering alternatives over statistics and within-day counting; no competitor named except the implied 'original' Streaks.")
ext("C185", " Report 62 (Streaks, yusuf kildan): praise_ui_design 6 (13.33%, 4.17★) sits beside the cap-driven uninstall — 'Really clean, minimal UI and super easy to use' then 'so I ended up uninstalling'.")
ext("C171", " Report 62 (Streaks, yusuf kildan): an app that cannot be operated by tapping is an accessibility failure in effect — the June build; zero explicit accessibility requests otherwise.")

